// ── Estimation helper — back-of-envelope in code form ───────────
const DAU       = 10_000_000;          // 10 M daily active users
const reqPerDay = 50;                  // requests per user per day
const avgSizeKB = 2;                   // average request payload KB

const totalReqPerDay   = DAU * reqPerDay;
const qps              = Math.round(totalReqPerDay / 86_400); // seconds per day
const peakQPS          = qps * 3;      // assume 3× peak multiplier
const storagePerDayGB  = (totalReqPerDay * avgSizeKB) / (1024 * 1024);
const storagePerYearTB = storagePerDayGB * 365 / 1024;

console.log(`QPS (avg):    ${qps}`);
console.log(`QPS (peak):   ${peakQPS}`);
console.log(`Storage/day:  ${storagePerDayGB.toFixed(1)} GB`);
console.log(`Storage/year: ${storagePerYearTB.toFixed(1)} TB`);

