// ── Simple consistent-hash ring (deep-dive concept) ───────────────
function hashCode(key) {
  let hash = 0;
  for (const ch of key) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
  return hash;
}

class ConsistentHashRing {
  constructor(nodes, replicas = 3) {
    this.ring = new Map();
    this.sorted = [];
    for (const node of nodes) this._addNode(node, replicas);
  }
  _addNode(node, replicas) {
    for (let i = 0; i < replicas; i++) {
      const h = hashCode(`${node}:${i}`);
      this.ring.set(h, node);
      this.sorted.push(h);
    }
    this.sorted.sort((a, b) => a - b);
  }
  getNode(key) {
    const h = hashCode(key);
    const pos = this.sorted.findIndex(v => v >= h);
    const idx = pos === -1 ? 0 : pos;
    return this.ring.get(this.sorted[idx]);
  }
}

const ring = new ConsistentHashRing(['server-A', 'server-B', 'server-C']);
console.log(ring.getNode('user-1234')); // deterministic server assignment
console.log(ring.getNode('user-5678'));

// ── Rate Limiter: token bucket (deep-dive pattern) ───────────────
class TokenBucketRateLimiter {
  constructor(capacity, refillRatePerSec) {
    this.capacity = capacity;
    this.tokens = capacity;
    this.refillRate = refillRatePerSec;
    this.lastRefill = Date.now();
  }
  _refill() {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(this.capacity, this.tokens + elapsed * this.refillRate);
    this.lastRefill = now;
  }
  allow() {
    this._refill();
    if (this.tokens >= 1) { this.tokens--; return true; }
    return false; // rate limited
  }
}
const limiter = new TokenBucketRateLimiter(5, 2); // 5 cap, 2/sec refill
for (let i = 0; i < 7; i++) console.log(`req ${i+1}: ${limiter.allow() ? 'OK' : 'BLOCKED'}`);

// ── Cache-aside pattern (read strategy) ──────────────────────────
async function getUser(id, cache, db) {
  const cached = await cache.get(`user:${id}`);
  if (cached) return JSON.parse(cached); // cache HIT
  const user = await db.findById(id);    // cache MISS — go to DB
  await cache.set(`user:${id}`, JSON.stringify(user), 'EX', 3600);
  return user;
}
